"use strict";
const $=s=>document.querySelector(s);
const e=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const state={token:"",projects:[],project:null,metrics:{},workerMetrics:null,events:[],settings:{},jobs:[],models:null,view:"overview",filter:"all",search:"",seenJobs:new Set(),watchedJobs:new Set(),demoSpec:"",busy:false};
const names={overview:"Overview",board:"Mission board",comms:"Shared comms",models:"Model workshop",diagnostics:"Diagnostics"};
const label=s=>String(s??"").replaceAll("_"," ");
const num=n=>Number(n||0).toLocaleString();
const short=s=>s?String(s).slice(0,10):"—";
const bytes=n=>n>=1e9?(n/1e9).toFixed(1)+" GB":n>=1e6?(n/1e6).toFixed(1)+" MB":n>=1000?(n/1000).toFixed(1)+" KB":num(n)+" B";
const time=s=>new Date(s).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit"});
function toast(text,error=false){const el=document.createElement("div");el.className="toast"+(error?" error":"");el.innerHTML=`<button aria-label="Dismiss notification">×</button>${e(text)}`;el.querySelector("button").onclick=()=>el.remove();$("#toasts").append(el);setTimeout(()=>el.remove(),error?14000:7000);}
async function api(path,data,raw=false){const response=await fetch(path,{method:data===undefined?"GET":"POST",headers:{"X-Station-Token":state.token,...(data===undefined?{}:{"Content-Type":"application/json"})},...(data===undefined?{}:{body:JSON.stringify(data)})});if(!response.ok){let err;try{err=await response.json();}catch{err={error:"Station is unavailable. Refresh to reconnect."};}throw Error(err.error||"Request failed");}return raw?response:response.json();}
function badge(s){let color=["integrated","approved"].includes(s)?"":s==="review_ready"?"teal":["blocked","repair_required"].includes(s)?"amber":"gray";return `<span class="tag ${color}">${e(label(s))}</span>`;}
function pageTitle(kicker,title,subtitle,actions=""){return `<div class="page-heading"><div><span class="eyebrow">${e(kicker)}</span><h1>${e(title)}</h1><p>${e(subtitle)}</p></div><div class="button-row">${actions}</div></div>`;}
function button(text,action,primary=false,attrs=""){return `<button type="button" class="button${primary?" primary":""}" data-action="${action}" ${attrs}>${text}</button>`;}
function noProject(){return `<div class="panel empty"><div class="empty-icon">▤</div><h2>Your next mission starts here.</h2><p>Import a Markdown specification, or run the Night Shift training mission to see the complete workflow.</p><div class="button-row">${button("+ New mission","new-project",true)}${button("Load training mission","demo")}</div></div>`;}
function metricsHTML(){const m=state.metrics,p=state.project,tasks=p?.tasks||[],done=tasks.filter(t=>t.state==="integrated").length;return `<div class="stats"><div class="stat"><div class="label">MISSION PROGRESS <span>▤</span></div><div class="value green">${done}<em> / ${tasks.length} integrated</em></div><small>${tasks.length?Math.round(done/tasks.length*100):0}% of specifications accepted</small></div><div class="stat"><div class="label">LOCAL TOKENS <span>▦</span></div><div class="value">${num((m.local_input||0)+(m.local_output||0))}</div><small>${p?.mode==="demo"?"Scripted demo · no model calls":"Provider-reported input + output"}</small></div><div class="stat"><div class="label">CLOUD TOKENS <span>⌁</span></div><div class="value teal">${num((m.cloud_input||0)+(m.cloud_output||0))}</div><small>${p?.allow_cloud?"Scoped escalation enabled":"Cloud sharing disabled"}</small></div><div class="stat"><div class="label">WORKFLOW EVENTS <span>⌘</span></div><div class="value">${num(m.events)}</div><small>Validated by code · no inference</small></div></div>`;}
function eventText(ev){const d=ev.data||{};switch(ev.event_type){case"project.created":return `Mission loaded · ${d.tasks} specifications ready for triage`;case"task.transition":return `${ev.task_id}: ${label(d.from)} → ${label(d.to)}`;case"task.claimed":return `${ev.task_id} assigned to ${ev.actor} · ${d.route} execution`;case"checks.completed":return `${ev.task_id}: ${d.passed}/${d.total} acceptance checks passed`;case"review.completed":return `${ev.task_id}: review ${d.approved?"approved":"requested changes"} · ${short(d.head_commit)}`;case"integration.completed":return `${ev.task_id} integrated at ${short(d.head_commit)}`;case"usage.recorded":return `${d.role}: ${d.source==="reported"?num((d.input_tokens||0)+(d.output_tokens||0))+" reported tokens":"token usage unavailable"}`;case"report.generated":return "Cloud swarm assessment ready";case"release.exported":return `Release bundle created · ${short(d.head_commit)}`;case"project.note":case"task.finding":return d.message||"Finding recorded";default:return label(ev.event_type.replaceAll("."," "));}}
function taskRow(t){return `<div class="task-row" data-action="task-detail" data-id="${e(t.id)}" role="button" tabindex="0"><span class="task-status ${t.state==="integrated"?"":"wait"}">${t.state==="integrated"?"✓":"▢"}</span><div><strong>${e(t.title)}</strong><small>${e(t.id)} · ${e(t.route)} runner</small></div>${badge(t.state)}</div>`;}
function overview(){const p=state.project, tasks=p?.tasks||[],m=state.metrics;const attention=tasks.filter(t=>["blocked","repair_required"].includes(t.state)).length;return pageTitle("SHIFT LOG / COMMAND CENTER","Welcome to the night shift.","Specs in. Verified work out. Your compute, under control.",button("+ New mission","new-project"))+`<section class="hero"><img src="/scene.svg" alt="Pixel art operations room overlooking a nighttime factory skyline"><div class="hero-copy"><span class="eyebrow">LOCAL RUNNERS. CLOUD BACKUP. ONE STATION.</span><h2>Keep the station<br>moving forward.</h2><p>Turn your specifications into parallel work, with checks and evidence at every handoff.</p><div class="button-row">${p?button(p.paused?"▶ Resume mission":"▶ Run mission","run-project",true):button("▶ Run training mission","demo",true)}${button("Open model workshop ↗","go-models")}</div></div><span class="hero-label">SECTOR 04 / OPERATIONS ONLINE</span></section>`+metricsHTML()+(p?.mode==="demo"?`<div class="callout info setup-hint"><span><b>TRAINING MODE</b> · Scripted proposals, real Git changes and acceptance checks. No LLM or cloud charges.</span><button class="text-button" data-action="new-project">Start a real mission ↗</button></div>`:"")+(!p?`<div class="callout setup-hint"><span><b>First shift?</b> Run the training mission now, then connect a local model in the workshop.</span><button class="text-button" data-action="setup">Open setup checklist ↗</button></div>`:"")+`<div class="grid-two"><section class="panel"><div class="panel-head"><h2>${p?e(p.name):"Mission queue"}</h2>${p?badge(p.paused?"blocked":p.tasks.every(t=>t.state==="integrated")?"integrated":p.tasks.some(t=>t.state==="running")?"running":"ready"):"<span class='tag gray'>Awaiting assignment</span>"}</div>${p?`<div class="panel-body"><div class="progress-label"><span>SPECIFICATION TO INTEGRATION</span><span>${attention?attention+" need attention":"All systems nominal"}</span></div><div class="progress-track">${tasks.map(t=>`<span class="${t.state==="integrated"?"done":["running","approved","review_ready"].includes(t.state)?"active":["blocked","repair_required"].includes(t.state)?"failed":""}"></span>`).join("")}</div></div>${tasks.slice(0,6).map(taskRow).join("")}<div class="panel-body"><button class="text-button" data-action="go-board">View mission board →</button></div>`:noProject()}</section><div><section class="panel"><div class="panel-head"><h2>Execution routes</h2><span class="eyebrow">BYO LLM</span></div><div class="panel-body"><div class="route-row"><div><b>▦ Local runner</b><small>${e(state.settings.local?.model||"Choose a model")}</small></div><span class="tag">ON DEVICE</span></div><div class="route-row"><div><b>⌁ Cloud support</b><small>${e(state.settings.cloud?.model||"Connect your provider")}</small></div><span class="tag ${state.settings.cloud?.model?"teal":"gray"}">${state.settings.cloud?.model?"CONFIGURED":"OPTIONAL"}</span></div><div class="route-row"><div><b>◇ Review gate</b><small>Checks + revision-bound review</small></div><span class="tag gray">${e(state.settings.review_placement||"local")}</span></div></div></section><section class="panel"><div class="panel-head"><h2>Latest signals</h2><button class="text-button" data-action="go-comms">Open comms ↗</button></div><div class="panel-body">${state.events.length?state.events.slice(-4).reverse().map(ev=>`<div class="activity-item"><span class="activity-dot"></span><div><p>${e(eventText(ev))}</p><small>${e(time(ev.timestamp))} · ${e(ev.actor)}</small></div></div>`).join(""):`<div class="activity-item"><span class="activity-dot"></span><div><p>Command station is online.</p><small>WAITING FOR YOUR FIRST MISSION</small></div></div>`}</div></section></div></div>`;}
function runControl(p){const r=p?.last_run;if(!r)return "";return `<section class="panel setup-hint"><div class="panel-head"><h2>Run control</h2>${badge(r.outcome)}</div><div class="panel-body"><div class="button-row"><span class="tag gray">${r.passes} passes</span><span class="tag gray">${p.mode==="demo"?"Training · no model calls":r.tokens===null?"Usage unknown":num(r.tokens)+" reported tokens"}</span><span class="tag gray">${r.wall_clock_s}s elapsed</span>${button("Open run receipt","artifact",false,`data-id="${e(r.evidence)}"`)}</div>${r.trip_reasons.length?`<p class="small-text muted section-gap">${e(r.trip_reasons.join(" · "))}</p>`:""}</div></section>`;}
function board(){const p=state.project;let h=pageTitle("OPERATIONS / SPECIFICATION TRACKER","Mission board","Every task has a scope, an owner, and a verifiable outcome.",p?button("↓ Project Markdown","download-markdown")+button("▶ Run mission","run-project",true):button("+ New mission","new-project",true));if(!p)return h+noProject();const columns=[{name:"Queued",states:["proposed","triaging","ready"]},{name:"In progress",states:["running","local_verified"]},{name:"Review & repair",states:["review_ready","approved","repair_required","blocked"]},{name:"Integrated",states:["integrated"]}];const filtered=p.tasks.filter(t=>(state.filter==="all"||state.filter==="attention"&&["repair_required","blocked"].includes(t.state)||state.filter==="cloud"&&t.route==="cloud")&&(`${t.id} ${t.title}`.toLowerCase().includes(state.search.toLowerCase())));return h+runControl(p)+`<div class="callout info setup-hint"><span><b>${e(p.name)}</b> · ${p.tasks.length} specifications · ${p.mode==="demo"?"Training mode":p.allow_cloud?"Local + cloud enabled":"Local only"}</span><div class="button-row">${button("Triage locally","triage-project")}${button(p.paused?"Resume":"Pause dispatch","pause-project")}</div></div><div class="filterbar"><div class="filter-tabs">${[["all","All tasks"],["attention","Needs attention"],["cloud","Cloud route"]].map(([v,t])=>`<button data-action="filter" data-value="${v}" class="${state.filter===v?"active":""}">${t}</button>`).join("")}</div><label class="sr-only" for="task-search">Search tasks</label><input id="task-search" placeholder="Search tasks…" value="${e(state.search)}"></div><div class="board">${columns.map(col=>{const ts=filtered.filter(t=>col.states.includes(t.state));return `<section class="board-column"><div class="column-title">${col.name}<span>${ts.length.toString().padStart(2,"0")}</span></div>${ts.length?ts.map(t=>`<article class="task-card" tabindex="0" role="button" data-action="task-detail" data-id="${e(t.id)}"><div class="task-id">${e(t.id)}<span>${t.route==="cloud"?"⌁":"▦"}</span></div><h3>${e(t.title)}</h3>${badge(t.state)}<p>${t.findings.length?e(t.findings[0].slice(0,95)):t.depends_on.length?"After "+e(t.depends_on.join(", ")):"Independent assignment"}</p><footer><span>${e(t.owner||"Unassigned")}</span><span>${t.checks_result.filter(c=>c.passed).length}/${t.checks.length} checks</span></footer></article>`).join(""):`<div class="column-empty">${col.name==="Integrated"?"Verified work lands here.":"No tasks in this lane."}</div>`}</section>`;}).join("")}</div><div class="section-gap button-row">${button("Export verified release","export-project",false,p.tasks.every(t=>t.state==="integrated")?"":"disabled")}${button("View consolidated report","report-preview")}</div>`;}
function comms(){const p=state.project;let h=pageTitle("COMMUNICATIONS / SHARED EVENT LOG","Keep everyone in sync.","Compact facts from workers. Consolidated by code. Interpreted when needed.",p?button("Consolidated report","report-preview")+button("⌁ Cloud assessment","cloud-report",true,p.allow_cloud?"":"disabled"):"");if(!p)return h+noProject();return h+`<div class="grid-two"><section class="panel"><div class="panel-head"><h2># ${e(p.name)}</h2><span class="tag teal">LDD EVENTS</span></div><div class="feed" id="event-feed">${state.events.map(ev=>{let cloud=ev.actor.includes("cloud"),user=ev.actor==="operator";return `<article class="message"><div class="avatar ${cloud?"cloud":user?"user":""}">${cloud?"CL":user?"OP":ev.actor==="reviewer"?"RV":"RN"}</div><div><div class="message-head"><strong>${e(ev.actor)}</strong><time>${e(time(ev.timestamp))}</time></div><p>${e(eventText(ev))}</p><code>#${ev.seq} · ${e(ev.event_type)}</code>${ev.data.evidence?`<div><button class="text-button" data-action="artifact" data-id="${e(ev.data.evidence)}">Open evidence ↗</button></div>`:""}</div></article>`;}).join("")}</div><form id="note-form" class="compose"><label class="sr-only" for="note-message">Post an operator note</label><input id="note-message" name="message" placeholder="Leave a note for this mission…" maxlength="2000" required><button class="button" type="submit">Post ↗</button></form></section><div><section class="panel"><div class="panel-head"><h2>One feed. Scoped delivery.</h2></div><div class="panel-body"><p class="small-text muted">The chat displays recorded activity. Agents receive task-specific context and report deltas, rather than replaying this conversation.</p><div class="route-row"><div><b>Runner</b><small>Assigned specification + scoped files</small></div><span class="teal">01</span></div><div class="route-row"><div><b>Coordinator</b><small>Deterministic transitions + evidence</small></div><span class="teal">02</span></div><div class="route-row"><div><b>Cloud swarm</b><small>Planning, diagnostics, integration analysis</small></div><span class="teal">03</span></div></div></section><section class="panel"><div class="panel-head"><h2>Report checkpoint</h2></div><div class="panel-body"><p class="small-text muted">A successful cloud assessment acknowledges its last event. The next assessment receives new events plus the current task snapshot.</p><span class="token-inline">${bytes(state.metrics.report_bytes||0)} consolidated payload</span><p class="small-text muted section-gap">Bytes describe the report size. Token counts come from model responses; no estimated savings are presented as measured results.</p></div></section></div></div>`;}
function runtimeHTML(){const m=state.models;if(!m)return `<div class="runtime-banner"><span class="loader"></span><div class="runtime-copy"><h3>Checking local runtime…</h3><p>Your models stay on this machine.</p></div></div>`;return `<div class="runtime-banner"><div class="runtime-icon">▦</div><div class="runtime-copy"><h3>${m.connected?"Ollama is online":m.installed?"Local runtime is installed":"Set up your local model engine"}</h3><p>${m.connected?`${m.models.length} installed models · ${m.running.length} loaded in memory`:m.installed?"Start the engine to download models and run inference.":"Download a verified Ollama runtime here, or launch the all-in-one Docker package."} · ${e(m.platform)} · ${m.disk_free_gb} GB free</p></div><div class="button-row">${!m.installed?button("↓ Install runtime","install-runtime",true):!m.connected?button("▶ Start engine","start-runtime",true):m.managed?button("Stop engine","stop-runtime"):""}${button("↻ Refresh","refresh-models")}</div></div>`;}
function providerOptions(selected,local=false){return Object.entries(state.settings.providers||{}).filter(([k])=>!local||["ollama","openai_compatible"].includes(k)).map(([k,v])=>`<option value="${e(k)}" ${selected===k?"selected":""}>${e(v.label)}</option>`).join("");}
function routeFields(prefix,p,local=false){const k=p.kind||"openai_compatible",saved=state.settings.credential_status?.[k]?.saved;return `<div class="form-grid route-profile" data-prefix="${e(prefix)}"><div class="field"><label for="${prefix}-kind">${local?"Local":"Cloud"} provider</label><select id="${prefix}-kind" name="${prefix}-kind" data-provider-select="${prefix}">${providerOptions(k,local)}</select></div><div class="field"><label for="${prefix}-model">${local?"Local runner model":"Model / deployment ID"}</label><input id="${prefix}-model" name="${prefix}-model" value="${e(p.model)}" ${local?"required":""} placeholder="Your model ID"></div><div class="field full"><label for="${prefix}-url">${local?"Local endpoint":"API endpoint"}</label><input id="${prefix}-url" name="${prefix}-url" value="${e(p.base_url)}" placeholder="${e(state.settings.providers?.[k]?.base_url||"Your HTTPS endpoint")}"><small>${local?"Loopback only. Compatible servers may need /v1.":"Provider defaults are filled automatically. Azure requires your resource endpoint."}</small></div><div class="field provider-token" ${["openai","openai_compatible","azure"].includes(k)?"":"hidden"}><label for="${prefix}-cap">Output-limit field</label><select id="${prefix}-cap" name="${prefix}-cap"><option ${p.output_token_field==="max_completion_tokens"?"selected":""}>max_completion_tokens</option><option ${p.output_token_field==="max_tokens"?"selected":""}>max_tokens</option></select></div><div class="field provider-azure" ${k==="azure"?"":"hidden"}><label for="${prefix}-version">Azure API version</label><input id="${prefix}-version" name="${prefix}-version" value="${e(p.api_version||"2024-10-21")}"></div>${local?"":`<div class="field provider-key" ${k==="bedrock"?"hidden":""}><label for="${prefix}-key">API key</label><input id="${prefix}-key" name="${prefix}-key" type="password" autocomplete="new-password" placeholder="${saved?"Saved for this provider · blank keeps it":"Saved only on this station"}"></div><div class="field provider-bedrock" ${k==="bedrock"?"":"hidden"}><label for="${prefix}-region">AWS region</label><input id="${prefix}-region" name="${prefix}-region" value="${e(p.region||"us-east-1")}"></div>${["access_key","secret_key","session_token"].map(name=>`<div class="field provider-bedrock" ${k==="bedrock"?"":"hidden"}><label for="${prefix}-${name}">AWS ${e(label(name))}${name==="session_token"?" (optional)":""}</label><input id="${prefix}-${name}" name="${prefix}-${name}" type="password" autocomplete="new-password" placeholder="${saved?"Saved · blank keeps it":"Or use an environment variable"}"></div>`).join("")}<div class="field full"><label class="check-label"><input name="${prefix}-clear" type="checkbox"><span>Remove this provider’s saved credentials</span></label></div>`}</div>`;}
function modelForm(){const s=state.settings;return `<form id="settings-form"><h3>Local execution</h3>${routeFields("local",s.local||{},true)}<div class="field section-gap"><label for="local-key">Local server API key <small>optional</small></label><input id="local-key" name="local-key" type="password" autocomplete="new-password" placeholder="${s.has_local_key?"Saved · blank keeps it":"Usually unnecessary for Ollama"}"><label class="check-label"><input name="local-clear" type="checkbox"><span>Remove local server key</span></label></div><div class="field section-gap"><label for="local-failover">Local fallback models <small>optional</small></label><input id="local-failover" name="local-failover" value="${e((s.local_failover||[]).join(", "))}" placeholder="model:tag, another:tag"><small>Same local endpoint. Tried in order after a connection, rate-limit, or server error.</small></div><h3 class="section-gap">Cloud support</h3>${routeFields("cloud",s.cloud||{})}<details class="route-details section-gap"><summary>Cloud failover order <span class="tag gray">OPTIONAL</span></summary><p class="small-text muted">Up to three other providers. Each attempted request counts toward the mission budget. Cloud sharing must be enabled for the mission.</p><div id="fallback-profiles">${(s.cloud_fallbacks||[]).map((p,i)=>fallbackFields(p,i)).join("")}</div>${button("+ Add fallback provider","add-fallback")}</details><div class="form-grid section-gap"><div class="field"><label for="review-placement">Review model</label><select id="review-placement" name="review-placement"><option value="local" ${s.review_placement==="local"?"selected":""}>Local route</option><option value="cloud" ${s.review_placement==="cloud"?"selected":""}>Cloud route</option></select></div><div class="field"><label for="workers">Parallel implementation runners</label><input id="workers" name="workers" type="number" min="1" max="8" value="${s.workers||2}"></div><div class="field"><label for="output-tokens">Maximum output tokens per call</label><input id="output-tokens" name="output-tokens" type="number" min="256" max="16000" value="${s.max_output_tokens||4096}"></div></div><details class="route-details section-gap"><summary>Mission loop limits</summary><p class="small-text muted">Limits apply to each batch after local triage. Checks run between dependency waves; active calls use their own timeouts. Unknown token usage stops further waves.</p><div class="form-grid"><div class="field"><label for="batch-passes">Maximum passes</label><input id="batch-passes" name="batch-passes" type="number" min="1" max="300" value="${s.batch_max_passes||30}"></div><div class="field"><label for="batch-tokens">Reported token budget</label><input id="batch-tokens" name="batch-tokens" type="number" min="1" max="10000000" value="${s.batch_token_budget||200000}"></div><div class="field"><label for="batch-seconds">Time budget (seconds)</label><input id="batch-seconds" name="batch-seconds" type="number" min="1" max="86400" value="${s.batch_wall_clock_s||3600}"></div></div></details><div class="section-gap"></div><div class="button-row"><button class="button primary" type="submit">Save model routes</button>${button("Test local connection","test-local")}${button("Test cloud connection","test-cloud")}${button("List cloud models","discover-cloud")}</div><p class="small-text muted section-gap">Save routes before testing. Keys stay with their provider. Bedrock uses sync Converse and async chat; streaming is unavailable. Azure and Bedrock IDs are entered manually.</p></form>`;}
function fallbackFields(p,i){return `<fieldset class="fallback-profile" data-index="${i}"><legend>Fallback ${i+1}</legend>${routeFields("fallback-"+i,p)}${button("Remove fallback","remove-fallback")}</fieldset>`;}
function readRoute(d,prefix){return {kind:d.get(prefix+"-kind"),model:d.get(prefix+"-model").trim(),base_url:d.get(prefix+"-url").trim(),output_token_field:d.get(prefix+"-cap"),api_version:d.get(prefix+"-version"),region:d.get(prefix+"-region")||"us-east-1"};}
function readCredentials(d,prefix,result){const kind=d.get(prefix+"-kind"),values={};for(const name of kind==="bedrock"?["access_key","secret_key","session_token"]:["api_key"]){const value=d.get(prefix+"-"+(name==="api_key"?"key":name));if(value)values[name]=value;}if(d.has(prefix+"-clear"))values.clear=true;if(Object.keys(values).length)result[kind]=values;}
async function saveRoutes(d){const credentials={};readCredentials(d,"cloud",credentials);const fallbacks=[...document.querySelectorAll('.fallback-profile')].map(el=>{const prefix="fallback-"+el.dataset.index;readCredentials(d,prefix,credentials);return readRoute(d,prefix);});state.settings=await api("/api/settings",{local:readRoute(d,"local"),cloud:readRoute(d,"cloud"),cloud_fallbacks:fallbacks,local_failover:d.get("local-failover").split(",").map(s=>s.trim()).filter(Boolean),provider_credentials:credentials,local_credentials:{api_key:d.get("local-key"),clear:d.has("local-clear")},review_placement:d.get("review-placement"),workers:Number(d.get("workers")),max_output_tokens:Number(d.get("output-tokens")),batch_max_passes:Number(d.get("batch-passes")),batch_token_budget:Number(d.get("batch-tokens")),batch_wall_clock_s:Number(d.get("batch-seconds"))});toast("Model routes saved");render();}
function observationPanel(){return `<section class="panel section-gap"><div class="panel-head"><h2>Observation console</h2><span class="tag teal">TRACE / VERIFY / REPLAY</span></div><div class="panel-body"><p class="small-text muted">Provider attempts and workflow signals stay on this station. Model prompts, outputs, and keys are excluded. Cloud reports retain their compact LDD facts.</p><div class="form-grid"><div class="field"><label for="observation-trace">Trace</label><select id="observation-trace"><option value="station">Model Workshop</option>${state.project?`<option value="${e(state.project.id)}" selected>Current mission</option>`:""}</select></div><div class="field"><label for="observation-kind">Event kind</label><select id="observation-kind"><option value="">All events</option>${["llm.request","llm.response","llm.failed","state.transition","handoff","checkpoint"].map(k=>`<option>${k}</option>`).join("")}</select></div></div><div class="button-row section-gap">${button("Inspect trace","inspect-observations",true)}${button("Download JSONL","export-observations")}${button(state.settings.observations_enabled?"Pause observations":"Resume observations","toggle-observations")}</div><div id="observation-summary" class="section-gap"></div><div id="observation-events" class="section-gap"><p class="small-text muted">Inspect a trace to verify its chain and browse the recorded signals.</p></div><button type="button" class="button small" id="observation-more" data-action="more-observations" hidden>Load more signals</button></div></section>`;}
async function loadObservations(more=false){const trace=$("#observation-trace").value,kind=$("#observation-kind").value;const qs=new URLSearchParams({trace,kind,after:more?String(state.observationCursor||0):"0"});const [page,summary]=await Promise.all([api("/api/observations?"+qs),api("/api/observations/summary?"+new URLSearchParams({trace}))]);state.observationCursor=page.next_cursor;state.observations=more?[...(state.observations||[]),...page.events]:page.events;$("#observation-summary").innerHTML=`<div class="callout ${summary.integrity==="verified"?"info":"warn"}"><b>${summary.integrity==="verified"?"CHAIN VERIFIED":"CHAIN CHECK FAILED"}</b> · ${num(summary.event_count)} records · ${num(summary.delivery_failures)} delivery failures<br><span class="mono small-text">${e(summary.head_hash)}</span></div><p class="small-text muted">${summary.enabled?"Recording enabled":"Recording paused"} · ${e(summary.anchor_scope)}</p>`;$("#observation-events").innerHTML=state.observations.length?state.observations.map((o,i)=>`<button type="button" class="observation-row" data-action="observation-detail" data-index="${i}"><span class="tag ${o.kind==="llm.failed"?"amber":"gray"}">${e(o.kind)}</span><span>${e(o.tags.provider||o.tags.actor||o.source)}<small>${e(o.tags.model||o.payload.task_id||"Station signal")}</small></span><code>${e(short(o.obs_id))} ↗</code></button>`).join(""):'<p class="small-text muted">No matching observations. Model Workshop records appear after a connection test or chat.</p>';$("#observation-more").hidden=!page.has_more;}

function models(){const m=state.models;return pageTitle("HARDWARE / MODELS / ROUTING","Your model workshop.","Install the engine, download a model, and route work from one place.")+`<div id="runtime-status">${runtimeHTML()}</div><div class="grid-two"><div><section class="panel"><div class="panel-head"><h2>Choose your local model</h2><a href="https://ollama.com/library" target="_blank" rel="noreferrer" class="text-button">Browse all models ↗</a></div><div class="panel-body"><div class="model-grid">${(m?.catalog||[{name:"qwen2.5-coder:3b",label:"Light runner",download:"1.9 GB",description:"Small, scoped edits. Lower memory footprint."},{name:"qwen2.5-coder:7b",label:"Code runner",download:"4.7 GB",description:"A starting point for implementation and local review."}]).map(c=>`<article class="model-card"><span class="eyebrow">LOCAL / CODING</span><h3>${e(c.label)}</h3><div class="model-name">${e(c.name)}</div><p>${e(c.description)}</p><footer><span>${e(c.download)}</span><button class="button small" data-action="pull-model" data-model="${e(c.name)}">↓ Download</button></footer></article>`).join("")}</div><form id="pull-form" class="inline-form section-gap"><label class="sr-only" for="custom-model">Custom Ollama model tag</label><input id="custom-model" name="model" placeholder="Or enter a model tag, e.g. qwen2.5-coder:14b" required><button class="button" type="submit">Download</button></form><p class="small-text muted section-gap">Download sizes are approximate. Memory needs also depend on context and concurrent runners. Models retain their respective licenses.</p><h3 class="section-gap">Installed on this station</h3><div id="installed-models">${installedHTML()}</div></div></section><section class="panel"><div class="panel-head"><h2>Quick model test</h2><span class="tag gray">SINGLE REQUEST</span></div><div class="panel-body"><form id="playground-form"><div class="field"><label for="playground-prompt">Message</label><textarea id="playground-prompt" name="prompt" rows="3" required placeholder="Write a Python health check for a service…"></textarea></div><div class="button-row"><select name="placement" aria-label="Playground model placement"><option value="local">Local model</option><option value="cloud">Cloud model</option></select><button class="button primary" type="submit">Send message ↗</button></div></form><div id="playground-result" class="result-box"></div></div></section></div><section class="panel"><div class="panel-head"><h2>Bring your own LLM</h2><span class="tag teal">PROVIDER ROUTES</span></div><div class="panel-body">${modelForm()}</div></section></div>`;}
function installedHTML(){if(!state.models?.connected)return `<p class="small-text muted">Start Ollama to list and manage installed models.</p>`;if(!state.models.models.length)return `<div class="column-empty">No models yet. Download one above to begin.</div>`;return state.models.models.map(m=>`<div class="model-row"><div><strong>${e(m.name)}</strong><small>${bytes(m.size)} · ${e(m.details?.quantization_level||"local")}${state.models.running.some(r=>r.name===m.name)?" · loaded":""}</small></div><div class="button-row"><button class="button small" data-action="select-model" data-model="${e(m.name)}">Use as runner</button><button class="text-button" data-action="unload-model" data-model="${e(m.name)}">Unload</button></div></div>`).join("");}
function workerTelemetryHTML(){const w=state.workerMetrics;if(!state.project)return `<p class="muted small-text">Load a mission to view distributed worker telemetry.</p>`;if(!w)return `<p class="muted small-text">Worker telemetry has not been loaded yet.</p>`;if(!w.workers.length)return `<p class="muted small-text">No remote worker telemetry is recorded for this mission yet.</p><p class="small-text muted section-gap">${e(w.identity_note)}</p>`;return `<div class="table-wrap"><table><thead><tr><th>Worker label</th><th>Claims</th><th>Tasks</th><th>Inference p50 / p95</th><th>Tokens</th><th>Expired</th></tr></thead><tbody>${w.workers.map(x=>`<tr><td><code>${e(x.worker)}</code></td><td>${num(x.claims)}</td><td>${num(x.tasks.length)}</td><td>${x.inference_latency.count?`${Math.round(x.inference_latency.median_ms)} / ${Math.round(x.inference_latency.p95_ms)} ms`:"unknown"}</td><td>${num(x.input_tokens+x.output_tokens)}</td><td>${num(x.expirations)}</td></tr>`).join("")}</tbody></table></div><p class="small-text muted section-gap">${e(w.identity_note)}</p>`;}
function diagnostics(){const p=state.project,m=state.metrics;return pageTitle("SYSTEM / EVIDENCE / ACCOUNTING","Follow the evidence.","Inspect check results, model usage, and the state behind each handoff.",p?button("↓ Project state","download-markdown"):"")+`<div class="grid-two"><div><section class="panel"><div class="panel-head"><h2>Station health</h2>${button("↻ Inspect","inspect-health")}</div><div class="panel-body" id="health-panel"><p class="small-text muted">Inspect your runtime, storage location, and connected services.</p></div></section><section class="panel"><div class="panel-head"><h2>Model usage</h2><span class="tag gray">REPORTED COUNTS</span></div><div class="panel-body">${p?`<div class="route-row"><span>Local input / output</span><span class="mono green">${num(m.local_input)} / ${num(m.local_output)}</span></div><div class="route-row"><span>Cloud input / output</span><span class="mono teal">${num(m.cloud_input)} / ${num(m.cloud_output)}</span></div><div class="route-row"><span>Model requests</span><span>${num(m.calls)}</span></div><div class="route-row"><span>Calls without reported usage</span><span class="amber">${num(m.unreported_calls)}</span></div><div class="route-row"><span>Request body bytes</span><span>${bytes(m.request_bytes||0)}</span></div><p class="small-text muted section-gap">Missing provider counts stay unknown. Training mode calls no model. Local hardware use and model downloads are not token charges.</p>`:`<p class="muted small-text">Load a mission to view its accounting.</p>`}</div></section><section class="panel"><div class="panel-head"><h2>Connect another runner</h2><span class="tag gray">OPTIONAL</span></div><div class="panel-body"><p class="small-text muted">Additional machines can claim scoped tasks and return file proposals. This station performs the checks and owns review approval.</p>${button("Configure runner access","worker-access")}<p class="small-text muted section-gap">For another machine, use a TLS reverse proxy or SSH tunnel. The default station is reachable only on your computer.</p></div></section><section class="panel"><div class="panel-head"><h2>Distributed worker telemetry</h2>${button("↻ Refresh","refresh-workers")}</div><div class="panel-body" id="worker-telemetry">${workerTelemetryHTML()}</div></section></div><section class="panel"><div class="panel-head"><h2>Operations history</h2><span class="eyebrow">LAST 40 JOBS</span></div><div class="table-wrap"><table><thead><tr><th>Operation</th><th>Result</th><th>Details</th></tr></thead><tbody>${state.jobs.length?state.jobs.map(j=>`<tr><td><code>${e(label(j.kind))}</code><br><span class="muted">${e(time(j.created_at))}</span></td><td>${badge(j.state)}</td><td>${e(j.detail)}${j.result?.id?`<br><button class="text-button" data-action="artifact" data-id="${e(j.result.id)}">Open result</button>`:""}</td></tr>`).join(""):`<tr><td colspan="3">No operations yet.</td></tr>`}</tbody></table></div></section></div>`+observationPanel();}
function render(){document.querySelectorAll("[data-view]").forEach(a=>a.classList.toggle("active",a.dataset.view===state.view));$("#page-label").textContent=names[state.view].toUpperCase();$("#main").innerHTML=({overview,board,comms,models,diagnostics}[state.view])();$("#footer-state").textContent=state.project?`${state.project.name} · ${state.project.paused?"Dispatch paused":state.project.mode==="demo"?"Training mode":"Mission online"}`:"Deterministic coordination. Evidence attached.";if(state.view==="comms"&&$("#event-feed"))$("#event-feed").scrollTop=$("#event-feed").scrollHeight;}
function openDialog(title,body,kicker="COMMAND STATION"){const d=$("#dialog");$("#dialog-title").textContent=title;$("#dialog-eyebrow").textContent=kicker;$("#dialog-body").innerHTML=body;if(!d.open)d.showModal();d.scrollTop=0;}
function setup(){openDialog("Ready for your first shift?",`<p class="muted small-text">The full Docker package includes Python, Git, and Ollama. On a native install, the workshop can install and start Ollama for you.</p><div class="setup-step"><span class="step-number">01</span><div><h3>Test the workflow</h3><p>The training mission demonstrates implementation, local tests, review, and integration without model downloads.</p></div>${button("Run training","demo")}</div><div class="setup-step"><span class="step-number">02</span><div><h3>Power up a local model</h3><p>Install or connect Ollama, download a model, and test it in the workshop.</p></div>${button("Open workshop","go-models")}</div><div class="setup-step"><span class="step-number">03</span><div><h3>Connect cloud support</h3><p>Add any compatible provider and select a review model. Each mission controls whether its source may leave the machine.</p></div>${button("Set routes","go-models")}</div><div class="setup-step"><span class="step-number">04</span><div><h3>Import your specification</h3><p>Use the Markdown template, point to a committed Git repository, and triage before dispatch.</p></div>${button("New mission","new-project",true)}</div>`,"STATION SETUP / 4 STEPS");}
function newProject(){openDialog("Start a new mission",`<form id="project-form"><div class="callout info">Use Markdown with one fenced JSON manifest. Define exact writable paths, dependencies, and acceptance checks. The station validates the manifest before importing.</div><div class="button-row"><button class="button small" type="button" data-action="load-template">Load template</button><button class="button small" type="button" data-action="upload-spec">↑ Open .md file</button><button class="button small" type="button" data-action="draft-spec">Draft with a model</button><input type="file" class="file-input" id="spec-upload" accept=".md,.markdown,.txt"></div><div class="field section-gap"><label for="project-spec">Specification Markdown</label><textarea id="project-spec" name="markdown" rows="13" required spellcheck="false" placeholder="# My project&#10;&#10;Describe your goal, then add a fenced JSON manifest.&#10;Use “Load template” to get started."></textarea></div><div class="field"><label for="project-source">Existing repository path <small>optional</small></label><input id="project-source" name="source" placeholder="/path/to/your/repo or C:\projects\your-repo"><small>Leave blank for a new workspace. Existing repositories must be clean and committed. Candidates and integrations live in a separate managed copy.</small></div><label class="check-label"><input type="checkbox" name="cloud"><span>Allow cloud processing for this mission<small>Scoped source, requirements, and evidence may be sent to your configured cloud provider.</small></span></label><label class="check-label"><input type="checkbox" name="commands"><span>Run this trusted project's test commands<small>Commands in the specification execute on the runner host with API keys removed from their environment. Native checks are not an OS sandbox.</small></span></label><div class="button-row section-gap"><button class="button" type="button" data-action="validate-spec">Validate specification</button><button class="button primary" type="submit">Create mission →</button></div><div id="spec-feedback" class="result-box"></div></form>`,"MISSION INTAKE / MARKDOWN");}
function taskDetail(id){const t=state.project?.tasks.find(t=>t.id===id);if(!t)return;const action=(name,op)=>`<button class="button ${op==="run"?"primary":""}" data-action="task-op" data-op="${op}" data-id="${e(id)}">${name}</button>`;openDialog(t.title,`<div class="button-row">${badge(t.state)}<span class="tag gray">${e(t.route)} route</span><span class="mono muted small-text">${e(t.id)}</span></div><p class="section-gap small-text">${e(t.instruction)}</p><dl class="detail-grid"><div class="detail-cell"><dt>Owner / attempt</dt><dd>${e(t.owner||"Unassigned")} / ${t.attempt}</dd></div><div class="detail-cell"><dt>Dependencies</dt><dd>${e(t.depends_on.join(", ")||"Independent")}</dd></div><div class="detail-cell"><dt>Base revision</dt><dd>${e(t.base_commit||"Not assigned")}</dd></div><div class="detail-cell"><dt>Candidate revision</dt><dd>${e(t.head_commit||"No candidate yet")}</dd></div></dl><h3>Writable files</h3><pre>${e(t.files.join("\n"))}</pre>${t.context.length?`<h3>Additional context</h3><pre>${e(t.context.join("\n"))}</pre>`:""}${t.findings.length?`<div class="callout warn"><b>Needs attention</b><ul class="info-list">${t.findings.map(f=>`<li>${e(f)}</li>`).join("")}</ul></div>`:""}<h3>Acceptance checks</h3>${t.checks.map((c,i)=>{let r=t.checks_result[i];return `<div class="check-row"><span class="${r?.passed?"green":"muted"}">${r?r.passed?"✓":"!":"▢"}</span><div>${e(label(c.kind))} · ${e(c.path||c.argv.join(" "))}<small>${r?e(r.detail.slice(0,240)):"Pending candidate verification"}</small></div></div>`;}).join("")}${t.verification_receipt?`<div class="callout info section-gap"><b>Bound verification receipt</b><p class="mono small-text receipt-hash">${e(t.verification_receipt.receipt.receipt_hash)}</p><small>${e(t.verification_receipt.receipt.payload.verifier_name)} · ${t.verification_receipt.receipt.payload.parent_receipts.length} prerequisite receipts. Open the station-receipt artifact below for the full binding.</small></div>`:""}<h3 class="section-gap">Evidence & patches</h3>${t.artifacts.length?t.artifacts.map(a=>`<div class="artifact-row"><span>${e(a.name)}<small class="muted"> · ${bytes(a.size)}</small></span><div class="button-row"><button class="text-button" data-action="artifact" data-id="${e(a.id)}">Inspect</button><button class="text-button" data-action="download-artifact" data-id="${e(a.id)}" data-name="${e(a.name)}">Download ↓</button></div></div>`).join(""):"<p class='small-text muted'>Receipts appear after the first implementation attempt.</p>"}<div class="button-row section-gap">${["ready","repair_required"].includes(t.state)?action("▶ Run task","run"):""}${t.state==="review_ready"?action("Review candidate","review"):""}${t.state==="approved"?action("Integrate verified change","integrate"):""}${state.project.allow_cloud&&t.route!=="cloud"&&["ready","repair_required","blocked"].includes(t.state)?action("Escalate to cloud","escalate"):""}${t.state==="blocked"?button("Re-triage mission","triage-project"):""}</div>`,"TASK / "+id);}
async function refreshProjects(){const r=await api("/api/projects");state.projects=r.projects;const saved=state.project?.id||localStorage.getItem("residual-project");const selected=r.projects.find(p=>p.id===saved)||r.projects[0]||null;const select=$("#project-select");select.innerHTML=r.projects.length?r.projects.map(p=>`<option value="${e(p.id)}">${e(p.name)}</option>`).join(""):"<option>No project loaded</option>";state.project=selected;if(selected){select.value=selected.id;localStorage.setItem("residual-project",selected.id);await refreshProject();}else{state.metrics={};state.events=[];}}
async function refreshProject(){if(!state.project)return;const [p,ev]=await Promise.all([api(`/api/projects/${state.project.id}`),api(`/api/projects/${state.project.id}/events?after=0`)]);state.project=p.project;state.metrics=p.metrics;state.events=ev.events;}
async function refreshWorkerMetrics(){if(!state.project){state.workerMetrics=null;return;}state.workerMetrics=await api(`/api/projects/${state.project.id}/workers`);if(state.view==="diagnostics")render();}
async function refreshModels(){state.models=await api("/api/models");if(state.view==="models"){if($("#runtime-status"))$("#runtime-status").innerHTML=runtimeHTML();if($("#installed-models"))$("#installed-models").innerHTML=installedHTML();}}
async function queue(path,data={}){const r=await api(path,data);if(r.job_id){state.watchedJobs.add(r.job_id);toast("Operation queued. Progress appears at the bottom of the station.");await pollJobs();}else if(r.message)toast(r.message);return r;}
async function download(path,name){const res=await api(path,undefined,true),blob=await res.blob(),url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function pollJobs(){const r=await api("/api/jobs");state.jobs=r.jobs;const active=r.jobs.filter(j=>["queued","running"].includes(j.state));const drafts=r.jobs.filter(j=>j.kind==="draft-spec"&&j.state==="completed"&&j.result?.markdown);const cards=active.slice(0,2).map(j=>`<div class="job-card"><strong>${e(label(j.kind))}</strong><small>${e(j.detail)}</small>${j.progress===null?"<progress aria-label='Operation progress'></progress>":`<progress max="100" value="${j.progress}" aria-label="Operation progress"></progress>`}</div>`);if(drafts.length)cards.push(`<button type="button" class="job-card job-result" data-action="open-draft" data-id="${e(drafts[0].id)}"><strong>DRAFT SPEC</strong><small>Completed · Open generated draft →</small></button>`);$("#job-tray").innerHTML=cards.join("");for(const j of r.jobs){if(!["completed","failed","interrupted"].includes(j.state)||state.seenJobs.has(j.id))continue;state.seenJobs.add(j.id);if(!state.watchedJobs.has(j.id))continue;state.watchedJobs.delete(j.id);if(j.state!=="completed"){toast(j.detail,true);continue;}toast(`${label(j.kind)} completed`);if(j.kind==="draft-spec"&&j.result?.markdown){newProject();$("#project-spec").value=j.result.markdown;toast("Draft loaded. Review file scope and acceptance checks before creating the mission.");}if(j.kind==="discover-models"&&j.result?.models){openDialog("Available model IDs",`<p class="small-text muted">Copy an ID into your provider route. Availability depends on your account and endpoint.</p><pre>${e(j.result.models.join("\n")||"No models returned by this endpoint.")}</pre>`);}if(j.kind==="playground"&&j.result?.text){if($("#playground-result"))$("#playground-result").innerHTML=`<pre>${e(j.result.text)}</pre><p class="small-text muted">Input: ${j.result.usage?.input_tokens??"unknown"} · Output: ${j.result.usage?.output_tokens??"unknown"}</p>`;else openDialog("Model response",`<pre>${e(j.result.text)}</pre>`);}if(j.kind.startsWith("test-")&&j.result?.text)toast(j.result.text);if(j.kind==="release"&&j.result?.id)await download(`/api/artifact?id=${encodeURIComponent(j.result.id)}&download=1`,j.result.name);if(["pull-model","install-runtime"].includes(j.kind))await refreshModels();}return active.length;}
async function action(el){const a=el.dataset.action,p=state.project;switch(a){case"open-draft":{const job=state.jobs.find(j=>j.id===el.dataset.id);if(!job?.result?.markdown){toast("This generated draft is no longer available.",true);return;}newProject();$("#project-spec").value=job.result.markdown;$("#project-spec").focus();toast("Draft loaded. Review file scope and acceptance checks before creating the mission.");return;}case"add-fallback":{const list=$("#fallback-profiles");if(list.children.length>=3){toast("Three fallback profiles is the maximum",true);return;}const used=[...document.querySelectorAll('[data-provider-select]')].map(el=>el.value);const kind=Object.keys(state.settings.providers).find(k=>!used.includes(k))||"anthropic";const i=Math.max(-1,...[...list.children].map(el=>Number(el.dataset.index)))+1;list.insertAdjacentHTML("beforeend",fallbackFields({kind,base_url:state.settings.providers[kind].base_url},i));return;}case"remove-fallback":el.closest(".fallback-profile").remove();return;case"discover-cloud":await queue("/api/providers/models",{placement:"cloud"});return;case"inspect-observations":await loadObservations();return;case"more-observations":await loadObservations(true);return;case"export-observations":await download("/api/observations/export?"+new URLSearchParams({trace:$("#observation-trace").value}),"observations.jsonl");return;case"toggle-observations":state.settings=await api("/api/settings",{observations_enabled:!state.settings.observations_enabled});el.textContent=state.settings.observations_enabled?"Pause observations":"Resume observations";await loadObservations();return;case"observation-detail":openDialog("Observation evidence",`<pre>${e(JSON.stringify(state.observations[Number(el.dataset.index)],null,2))}</pre>`);return;case"switch-project":openDialog("Switch mission",state.projects.length?state.projects.map(project=>`<div class="model-row"><div><strong>${e(project.name)}</strong><small>${project.tasks.filter(t=>t.state==="integrated").length}/${project.tasks.length} integrated · ${e(project.mode)}</small></div><button class="button small" data-action="select-project" data-id="${e(project.id)}">Open mission</button></div>`).join(""):noProject());return;case"select-project":state.project={id:el.dataset.id};localStorage.setItem("residual-project",el.dataset.id);await refreshProjects();$("#dialog").close();render();return;case"close-dialog":$("#dialog").close();return;case"setup":setup();return;case"new-project":newProject();return;case"go-models":case"go-board":case"go-comms":$("#dialog").close();location.hash=a.slice(3);return;case"demo":{el.disabled=true;const r=await api("/api/demo",{});localStorage.setItem("residual-project",r.project_id);state.project={id:r.project_id};$("#dialog").close();await refreshProjects();location.hash="overview";render();await queue(`/api/projects/${r.project_id}/run`);return;}case"run-project":if(!p)return;if(p.paused)await api(`/api/projects/${p.id}/pause`,{paused:false});await queue(`/api/projects/${p.id}/run`);return;case"triage-project":if(p){$("#dialog").close();await queue(`/api/projects/${p.id}/triage`);}return;case"pause-project":await api(`/api/projects/${p.id}/pause`,{paused:!p.paused});await refreshProject();render();return;case"download-markdown":await download(`/api/projects/${p.id}/markdown`,"PROJECT.md");return;case"task-detail":taskDetail(el.dataset.id);return;case"task-op":$("#dialog").close();await queue(`/api/projects/${p.id}/task`,{task_id:el.dataset.id,action:el.dataset.op});await refreshProject();render();return;case"filter":state.filter=el.dataset.value;render();return;case"report-preview":{const r=await api(`/api/projects/${p.id}/report`);openDialog("Consolidated project report",`<p class="small-text muted">Deterministically generated facts. Cloud interpretation is a separate operation.</p><pre>${e(JSON.stringify(r,null,2))}</pre>`);return;}case"cloud-report":await queue(`/api/projects/${p.id}/cloud-report`);return;case"export-project":await queue(`/api/projects/${p.id}/export`);return;case"artifact":{const res=await api(`/api/artifact?id=${encodeURIComponent(el.dataset.id)}`,undefined,true);if(res.headers.get("Content-Type").includes("zip")){await download(`/api/artifact?id=${encodeURIComponent(el.dataset.id)}&download=1`,"release.zip");return;}openDialog("Evidence inspector",`<p class="small-text muted mono">${e(el.dataset.id)}</p><pre>${e(await res.text())}</pre>`);return;}case"download-artifact":await download(`/api/artifact?id=${encodeURIComponent(el.dataset.id)}&download=1`,el.dataset.name);return;case"refresh-models":await refreshModels();toast(state.models.connected?"Local engine is online":"Ollama is not responding yet");return;case"start-runtime":await queue("/api/models/start");setTimeout(()=>refreshModels().catch(()=>{}),1500);return;case"stop-runtime":await queue("/api/models/stop");await refreshModels();return;case"install-runtime":await queue("/api/models/install");return;case"pull-model":await queue("/api/models/pull",{model:el.dataset.model});return;case"unload-model":await queue("/api/models/unload",{model:el.dataset.model});await refreshModels();return;case"select-model":{const local=state.settings.local;state.settings=await api("/api/settings",{local:{kind:"ollama",base_url:local.kind==="ollama"?local.base_url:"http://127.0.0.1:11434",model:el.dataset.model,output_token_field:"max_tokens"}});render();toast("Local runner selected");return;}case"test-local":case"test-cloud":await queue("/api/models/test",{placement:a.slice(5)});return;case"load-template":$("#project-spec").value=state.demoSpec.replace(/This training mission.*?\n/,'Review this template and adapt the files, requirements, and tests to your project.\n');return;case"upload-spec":$("#spec-upload").click();return;case"validate-spec":{const r=await api("/api/spec/validate",{markdown:$("#project-spec").value});$("#spec-feedback").innerHTML=`<div class="callout">✓ ${e(r.name)} · ${r.tasks} valid tasks</div>`;return;}case"draft-spec":openDialog("Draft a mission specification",`<form id="draft-form"><div class="field"><label for="draft-goal">What should the runners build?</label><textarea id="draft-goal" name="goal" rows="6" required placeholder="Describe the outcome, repository layout, constraints, and acceptance criteria."></textarea></div><div class="button-row"><select name="placement" aria-label="Planning model"><option value="local">Local planner</option><option value="cloud">Cloud planner</option></select><button class="button primary" type="submit">Generate draft</button></div><p class="muted small-text section-gap">The generated specification is a draft. You will inspect it before it becomes executable work.</p></form>`);return;case"inspect-health":{const h=await api("/api/diagnostics");$("#health-panel").innerHTML=Object.entries(h).map(([k,v])=>`<div class="route-row"><span>${e(label(k))}</span><code>${e(v)}</code></div>`).join("");return;}case"refresh-workers":await refreshWorkerMetrics();toast("Worker telemetry refreshed");return;case"worker-access":openDialog("Connect distributed runners",`<p class="small-text muted">A runner key permits claiming live tasks and reading their scoped source. Keep it on trusted machines. Results are proposals; verification stays on this station.</p><div class="button-row">${button("Enable & reveal key","enable-workers",true)}${button("Disable access","disable-workers")}${button("Rotate key","rotate-workers")}</div><div id="worker-result" class="section-gap"></div><p class="small-text muted section-gap">Run the bundled client with <code>python -m residual.station.worker --station https://your-station --project PROJECT_ID</code>. Supply the key through <code>RESIDUAL_WORKER_TOKEN</code>. See <code>docs/station/DISTRIBUTED.md</code>.</p>`);return;case"enable-workers":case"disable-workers":case"rotate-workers":{const r=await api("/api/workers/access",{enabled:a!=="disable-workers",rotate:a==="rotate-workers"});$("#worker-result").innerHTML=r.enabled?`<label for="worker-key">Runner access key</label><input id="worker-key" readonly value="${e(r.token)}"><p class="small-text muted">Project: <code>${e(p?.id||"Create a project first")}</code></p>`:"<div class='callout'>Remote runner access is disabled.</div>";return;}}}
document.addEventListener("click",async ev=>{const el=ev.target.closest("[data-action]");if(!el||el.disabled)return;try{await action(el);}catch(err){toast(err.message,true);}finally{if(el.dataset.action==="demo")el.disabled=false;}});
document.addEventListener("keydown",ev=>{if((ev.key==="Enter"||ev.key===" ")&&ev.target.matches("[role=button][data-action]")){ev.preventDefault();ev.target.click();}if(!$("#dialog").open&&!/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName)&&!ev.ctrlKey&&!ev.metaKey&&!ev.altKey&&/^[1-5]$/.test(ev.key))location.hash=Object.keys(names)[Number(ev.key)-1];});
document.addEventListener("input",ev=>{if(ev.target.id==="task-search"){const start=ev.target.selectionStart;state.search=ev.target.value;render();$("#task-search").focus();$("#task-search").setSelectionRange(start,start);}});
document.addEventListener("change",async ev=>{try{if(ev.target.dataset.providerSelect){const prefix=ev.target.dataset.providerSelect,k=ev.target.value,box=ev.target.closest(".route-profile");box.querySelector('[name="'+prefix+'-url"]').value=state.settings.providers[k].base_url;for(const cls of ["key","bedrock","azure","token"]){box.querySelectorAll(".provider-"+cls).forEach(el=>el.hidden=cls==="key"?k==="bedrock":cls==="bedrock"?k!=="bedrock":cls==="azure"?k!=="azure":!["openai","openai_compatible","azure"].includes(k));}box.querySelectorAll('[type="password"]').forEach(el=>{el.value="";el.placeholder=state.settings.credential_status?.[k]?.saved?"Saved for this provider · blank keeps it":"Stored only on this station";});}if(["observation-trace","observation-kind"].includes(ev.target.id)){await loadObservations();}if(ev.target.id==="project-select"){state.project={id:ev.target.value};await refreshProject();localStorage.setItem("residual-project",ev.target.value);render();}if(ev.target.id==="spec-upload"){const file=ev.target.files[0];if(file){if(file.size>250000)throw Error("Specification must be under 250 KB");$("#project-spec").value=await file.text();}}}catch(err){toast(err.message,true);}});
document.addEventListener("submit",async ev=>{ev.preventDefault();const f=ev.target,d=new FormData(f),submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{switch(f.id){case"project-form":{const r=await api("/api/projects",{markdown:d.get("markdown"),source:d.get("source"),allow_cloud:d.has("cloud"),commands:d.has("commands")});state.project={id:r.project_id};localStorage.setItem("residual-project",r.project_id);$("#dialog").close();await refreshProjects();location.hash="board";render();toast("Mission created. Run local triage before implementation.");break;}case"settings-form":await saveRoutes(d);break;case"pull-form":await queue("/api/models/pull",{model:d.get("model")});break;case"playground-form":await queue("/api/playground",{prompt:d.get("prompt"),placement:d.get("placement")});break;case"note-form":await api(`/api/projects/${state.project.id}/note`,{message:d.get("message")});await refreshProject();render();break;case"draft-form":await queue("/api/plan",{goal:d.get("goal"),placement:d.get("placement")});$("#dialog").close();break;}}catch(err){toast(err.message,true);}finally{if(submit)submit.disabled=false;}});
window.addEventListener("hashchange",()=>{const v=location.hash.slice(1);state.view=names[v]?v:"overview";render();if(state.view==="models")refreshModels().catch(err=>toast(err.message,true));if(state.view==="diagnostics")refreshWorkerMetrics().catch(err=>toast(err.message,true));});
async function boot(){try{const b=await api("/api/bootstrap");state.token=b.token;state.settings=b.settings;state.demoSpec=b.demo_spec;await refreshProjects();const j=await api("/api/jobs");state.jobs=j.jobs;j.jobs.forEach(x=>state.seenJobs.add(x.id));state.view=names[location.hash.slice(1)]?location.hash.slice(1):"overview";render();if(state.view==="models")refreshModels().catch(()=>{});if(state.view==="diagnostics")refreshWorkerMetrics().catch(()=>{});setInterval(async()=>{if(state.busy||document.hidden)return;state.busy=true;try{const active=await pollJobs();const old=JSON.stringify([state.project?.tasks,state.metrics]);await refreshProject();$("#connection").textContent="Station online";$("#connection").classList.remove("offline");if(!$("#dialog").open&&["overview","board","comms"].includes(state.view)&&!document.activeElement.matches("input,textarea,select,[contenteditable]")&&old!==JSON.stringify([state.project?.tasks,state.metrics]))render();}catch{$("#connection").textContent="Reconnecting…";$("#connection").classList.add("offline");}finally{state.busy=false;}},2200);}catch(err){$("#main").innerHTML=`<div class="empty"><h1>Station connection interrupted.</h1><p>${e(err.message)}</p><a class="button" href="/">Reconnect</a></div>`;}}boot();
